#include "theme.h"
uint16_t c565(uint8_t r, uint8_t g, uint8_t b) { return ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3); }
uint16_t cScale(uint16_t c, uint8_t pct) {
  uint8_t r = (c >> 11) & 31, g = (c >> 5) & 63, b = c & 31;
  return ((r * pct / 100) << 11) | ((g * pct / 100) << 5) | (b * pct / 100);
}
uint16_t cLerp(uint16_t a, uint16_t b, uint8_t t) {
  int ar = (a >> 11) & 31, ag = (a >> 5) & 63, ab = a & 31, br = (b >> 11) & 31, bg = (b >> 5) & 63, bb = b & 31;
  return ((ar + (br - ar) * t / 255) << 11) | ((ag + (bg - ag) * t / 255) << 5) | (ab + (bb - ab) * t / 255);
}
